const dimensions = 10;
const faceSize = 32;
const status = document.createElement("div");
status.textContent = "Loading celebrity faces...";
const image = IO.paintCelebrityFace(new Float32Array(faceSize * faceSize * 3), 16);
const coordinates = new Array(dimensions).fill(0);
let pca;
let ready = false;

const updateImage = () => {
    image.update(new Float32Array(pca.gen(coordinates).toArray()));
};

const sliders = Array.from({length: dimensions}, (_, i) => ({
    type: "slider",
    value: () => ({
        min: -1,
        max: 1,
        value: 0,
        title: `alpha_${i + 1}`,
        onChange: value => {
            coordinates[i] = value;
            if (ready) {
                try {
                    updateImage();
                } catch (error) {
                    console.error("Could not update face:", error);
                    status.textContent = `Could not update face: ${error.message}`;
                }
            }
        },
    }),
}));
const ui = IO.UI(
    {type: "canvas", value: () => status},
    {type: "canvas", value: () => image},
    ...sliders,
);

const initialize = async () => {
    const samples = await IO.loadCelebrityFaces(200);
    if (samples.length <= dimensions) throw new Error("At least 11 faces are required");
    status.textContent = "Computing PCA...";
    await new Promise(resolve => setTimeout(resolve, 0));
    pca = PCA.new(samples, dimensions);
    if (pca.principalValues.some(value => !Number.isFinite(value) || value <= 0)) {
        throw new Error("PCA could not find enough nonzero components");
    }
    updateImage();
    ready = true;
    status.textContent = `Ready. Exploring ${samples.length} celebrity faces.`;
};
setTimeout(() => {
    initialize().catch(error => {
        console.error("Could not initialize celebrity faces PCA:", error);
        status.textContent = `Could not initialize celebrity faces PCA: ${error.message}`;
    });
}, 0);
ui;
